package earth.terrarium.pastel.data.lang.guidebook.cuisine;

import net.neoforged.neoforge.common.data.LanguageProvider;

public class BrewersHandbookEntry {
	public static void addTranslations(LanguageProvider provider) {
		provider.add("book.pastel.guidebook.brewers_handbook.page0.text", "   *Reflection Of The Moon*");
		provider.add("book.pastel.guidebook.brewers_handbook.page0.title", "Brewing for the Deep");
		provider.add("book.pastel.guidebook.brewers_handbook.page1.text", "Hayo! The current state of relations between the overworld and the deep is rather poor, and sadly it seems to only be getting worse, and there's not much I can do about it.\\\n\\\nSo I've have taken some of my time to collect a bunch of brewing recipes from the surface, adapt them to use ingredients found in our depths, and publish that as a gift to you all, in the hope that it will aid you.");
		provider.add("book.pastel.guidebook.brewers_handbook.page10.text", "*Burns on the way down and when it gets there too.\\\n\\\n Great if you have someone you want to get hot and bothered.*");
		provider.add("book.pastel.guidebook.brewers_handbook.page13.text", "Hi. I'm sorry I did not get more to you all, this is all I could manage to sneak in - anything passing by the mouth of the caves is closely watched, and I myself can feel the gaze of the surface emperors scorching my back. I really, really wanted to do more, but the fact that I have to use a pseudonym should reveal the state of my condition. This is all I can do. I hope it will be enough.");
		provider.add("book.pastel.guidebook.brewers_handbook.page13.title", "[Hidden Page 1]");
		provider.add("book.pastel.guidebook.brewers_handbook.page14.text", "*This took a lot out of me to get working. Through this, you should be able to use blood orchid extract more aggressively. If worse comes to worst, it should give you an edge.*");
		provider.add("book.pastel.guidebook.brewers_handbook.page15.text", " ...Asteras\\\nI hope that this message will reach you. The state of things has only worsened since we last spoke, the nobles are still targeting you, but more worryingly.... They are preparing for war, it is clear by now. They want the Bloomstone, and they are willing to sacrifice a lot for it. Things are going to get bad, please stay safe.\\\n        *...I miss you.*");
		provider.add("book.pastel.guidebook.brewers_handbook.page15.title", "[Hidden Page 2]");
		provider.add("book.pastel.guidebook.brewers_handbook.page2.text", "\\\nHeya, glass peaches are not just for emperors!\\\n\\\nWe can enjoy them too! This quick and easy to follow recipe makes for a nice, creamy cup of peachy goodness - if you have any, and I understand why you don't, then sweet berries make for a great garnish!");
		provider.add("book.pastel.guidebook.brewers_handbook.page2.title", "Pink Cups");
		provider.add("book.pastel.guidebook.brewers_handbook.page3.text", "*Do not exchange the berries out for holly ones, they are no good...*");
		provider.add("book.pastel.guidebook.brewers_handbook.page4.text", "\\\nThose thickets of pyrite... they are I think my favorite places in the depths, there is something just so pretty about them, even considering for how dangerous just existing in them is.\\\n\\\nRegardless! While the berries of the bushes that grow there are poisonous, we can side step that...");
		provider.add("book.pastel.guidebook.brewers_handbook.page4.title", "Holly Hot Drinks");
		provider.add("book.pastel.guidebook.brewers_handbook.page5.text", "*But if you do want to use those holly berries for something, here you go.*");
		provider.add("book.pastel.guidebook.brewers_handbook.page6.text", "\\\nThis not mead, you could not legally call it mead, I am obligated to clarify it is not mead.\\\n\\\n\\\n So this mead is a bit of a favorite recipe of mine, it took a while to figure out how to adapt honey wine for a place that has no bees, but trust me, this genuinely outdoes the real deal.");
		provider.add("book.pastel.guidebook.brewers_handbook.page6.title", "Not Honey Wine");
		provider.add("book.pastel.guidebook.brewers_handbook.page7.text", "*Not a mead, no no no.*");
		provider.add("book.pastel.guidebook.brewers_handbook.page9.text", "\\\nMyceylon, that odd cinnamon-esque spice you all have down there. I am honestly really fond of the stuff, it reminds me of those long, tender nights I used to spend down there. Though like most, I associate the spice with a level of warmth and comfort, for me there is this undertone of longing...");
		provider.add("book.pastel.guidebook.brewers_handbook.page9.title", "Heat for the Heart");
	}
}
